SELECT *, NTILE(4) OVER (PARTITION BY customer_id, status ORDER BY balance DESC, id) AS balance_bucket, LAST_VALUE(balance) IGNORE NULLS OVER (PARTITION BY account_type, status ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_balance, SUM(balance) OVER (PARTITION BY customer_id, account_type ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_balance, LEAD(balance, 2, 0) OVER (PARTITION BY customer_id ORDER BY balance, id) AS next_balance, AVG(balance) OVER w_recent AS account_type_avg_balance FROM accounts WINDOW w_recent AS (PARTITION BY account_type);
